-- Ficha de Toque Profundo.
--
-- La biografía de relleno tenía dos frases sin un solo hecho. formation_year: 1989 (Hard
-- Rock Cafe Santo Domingo da la fecha exacta, 9 de agosto). Año del primer Casandra en
-- conflicto (1991/1992): se usa 1992; ver CONFLICTOS_DE_DATO.md. Tony Almont no tiene ficha
-- propia: ver ARTISTAS_FALTANTES.md.

UPDATE artists SET formation_year = 1989 WHERE slug = 'toque-profundo';

INSERT INTO award_categories (award_id, name)
SELECT a.id, 'Mejor Grupo de Rock' FROM awards a WHERE a.name = 'Premios Casandra'
   AND NOT EXISTS (SELECT 1 FROM award_categories c WHERE c.award_id = a.id AND c.name = 'Mejor Grupo de Rock');

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 1992, 'Sueños y pesadillas del tercer mundo', true, 'Diario Libre (25 mar 2006); Bandsintown; Centro León'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'toque-profundo' AND a.name = 'Premios Casandra' AND cat.name = 'Mejor Grupo de Rock'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 1992);

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2011, NULL, true, 'Wikipedia; Deezer; DominicanHipHop.com; Centro León'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'toque-profundo' AND a.name = 'Premios Casandra' AND cat.name = 'Mejor Grupo de Rock'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2011);

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2012, NULL, true, 'Wikipedia; Deezer; DominicanHipHop.com; Centro León'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'toque-profundo' AND a.name = 'Premios Casandra' AND cat.name = 'Mejor Grupo de Rock'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2012);

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2014, NULL, true, 'LaCarne Magazine (5 jun 2021); DominicanHipHop.com; indiexpuesto.com'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'toque-profundo' AND a.name = 'Premios Soberano' AND cat.name = 'Soberano al Mérito'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2014);

