SELECT d.id, '2f3ee7e7-43cd-49c2-aded-3c4220cce91e', 'artist', '9656dc3d-a19b-439b-a13c-17624ae1826a' FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id
